import{z as B,x as A,o as E,c as d,q as r,j as o,D as e,d as t,s,S as l,b as n}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"SELinux 类型强制","description":"","frontmatter":{"title":"SELinux 类型强制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/selinux-type-enforcement.md","filePath":"cs/selinux-type-enforcement.md","lastUpdated":1791063341000}'),p={name:"cs/selinux-type-enforcement.md"};function c(u,a,m,h,x,f){const i=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=r('<h1 id="selinux-类型强制" tabindex="-1">SELinux 类型强制 <a class="header-anchor" href="#selinux-类型强制" aria-label="Permalink to &quot;SELinux 类型强制&quot;">​</a></h1><div class="epigraph"><p>类型强制给进程与文件打类型标签，规则只允许指定的类型对流。即便进程以 root 跑，也不能任意读未允许的客体。策略是规格，不是建议。</p><footer>—— Loscocco and Smalley, Integrating Flexible Support for Security Policies into the Linux Operating System, USENIX 2001；NSA SELinux</footer></div><p>上一课<a href="/cs/red-blue-team">红蓝</a>结束网络防御。系统单元从强制访问起。主干<a href="/cs/dac-mac-rbac">DAC/MAC/RBAC</a>已给 MAC 名字。缺口是 <strong>SELinux 类型强制</strong>如何落到 Linux：标签、允许规则、最小特权。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DAC 的 root 全能。MAC：httpd_t 只能碰 httpd_sys_content_t 一类。缺口是策略编写与 permissive/enforcing，不是关闭 SELinux 当排错默认。</p><p><span class="marginnote">直觉类比：类型强制像机场安检——旅客（进程类型）和货舱（文件类型）各挂一个标签，规则写明哪类旅客能带哪类货。它不看「这位旅客是谁」，所以哪怕你是贵宾（root），该查的照样查。</span></p><p><span class="marginnote">常见误区：初学者容易把 SELinux 设成 permissive（只记日志不拦截）当「关掉排错」。实际上这层检查仍在跑，只是违规从「拦下」变成「写进 audit 日志」；正确姿势是先看 denied 记录，再补允许规则。</span></p><h3 id="容器" tabindex="-1">容器 <a class="header-anchor" href="#容器" aria-label="Permalink to &quot;容器&quot;">​</a></h3><p>容器常带自己的类型；错误的 unconfined 等于关掉这层。</p><p><span class="marginnote">Flask/TE。本课不写如何逃策略的步骤。提权下一课谈能力与 sudo 面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画主体类型、客体类型、允许。对照 AppArmor 路径名策略点名。下一课 Linux 提权路径：能力、SUID、配置。</p>',13)),(E(),o(l,null,{default:e(()=>[s(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E8%BF%9B%E7%A8%8B%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20RULE%5B%22%E5%85%81%E8%AE%B8%E8%A7%84%E5%88%99%22%5D%0A%20%20OBJ%5B%22%E6%96%87%E4%BB%B6%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20RULE%0A%20%20RULE%20--%3E%20DENY%5B%22%E6%9C%AA%E5%85%81%E8%AE%B8%E5%88%99%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[t("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"引用监视器在内核。策略错误会拒服务，于是有人关 SELinux——那是可用性打完整。提权课假设这层可能被配错。",-1)),a[5]||(a[5]=n("p",null,"上面那张图回答「允许规则由什么拼成」；下面这张回答一次真实的读文件请求在内核里走哪条路——先查缓存还是先查策略，决定了这一步的开销。",-1)),(E(),o(l,null,{default:e(()=>[s(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BF%9B%E7%A8%8B%E8%AF%B7%E6%B1%82%E8%AF%BB%E6%96%87%E4%BB%B6%22%5D%20--%3E%20B%5B%22%E5%86%85%E6%A0%B8%E5%8F%96%E5%87%BA%E4%B8%A4%E4%BE%A7%E7%B1%BB%E5%9E%8B%E6%A0%87%E7%AD%BE%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%85%88%E6%9F%A5%20AVC%20%E7%BC%93%E5%AD%98%22%5D%0A%20%20C%20--%3E%20D%7B%22%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20D%20--%20%22%E6%98%AF%22%20--%3E%20E%5B%22%E6%8C%89%E7%BC%93%E5%AD%98%E7%BB%93%E8%AE%BA%E6%94%BE%E8%A1%8C%E6%88%96%E6%8B%92%E7%BB%9D%22%5D%0A%20%20D%20--%20%22%E5%90%A6%22%20--%3E%20F%5B%22%E6%9F%A5%E5%AE%8C%E6%95%B4%E7%AD%96%E7%95%A5%E5%BA%93%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%86%99%E5%85%A5%20AVC%20%E5%B9%B6%E8%BF%94%E5%9B%9E%E7%BB%93%E8%AE%BA%22%5D%0A%20%20G%20--%3E%20E%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">术语翻译：AVC（Access Vector Cache，访问向量缓存）就是内核把最近用过的「类型对 → 允许/拒绝」结论缓存起来的手段，用来省掉每次翻策略库的开销——策略库是厚厚的规则手册，AVC 是贴在手边的便签。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写逃逸策略。Linux 提权路径下一课只讲机制与硬化，不给利用步骤。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>红蓝之后，系统层用 TE 限制即便是 root 的进程。</li><li>标签加允许规则；enforcing 才是策略。</li><li>关 SELinux 排错是把 MAC 撤掉。</li><li>下一课 Linux 提权路径。</li><li>出处：Loscocco and Smalley, 2001；对照 <a href="/cs/dac-mac-rbac">dac-mac-rbac</a>。</li></ul>',5))])}const _=B(p,[["render",c]]);export{S as __pageData,_ as default};
